<script setup>
import { onMounted, ref, reactive } from 'vue'
import { useQuasar } from 'quasar'
import { api } from 'boot/axios'
const $q = useQuasar(), items = ref([]), selected = ref(null), messages = ref([]), busy = ref(false), page = ref(1), pages = ref(1), messagePage = ref(1), messagePages = ref(1)
const filters = reactive({ category: '', flow: '' }), edit = reactive({ category: 'geral', status: 'open', tags: [] })
const categories = ['geral','aitonotify','api-oficial','botbuilder','ia','implantacao','integracoes','sistemas']
const headers = () => ({ headers: { Authorization: `Bearer ${localStorage.getItem('aito_admin_token') || ''}` } })
const failed = e => $q.notify({ type: 'negative', message: e.response?.data?.message || 'Não foi possível carregar o histórico.' })
async function load() { busy.value = true; try { const v = (await api.get('/admin/site-assistant/conversations', { ...headers(), params: { ...filters, page: page.value } })).data.data; items.value = v.items; pages.value = v.pages } catch(e) { failed(e) } finally { busy.value = false } }
async function open(item, current = 1) { try { const v = (await api.get('/admin/site-assistant/conversations/' + item.id, { ...headers(), params: { page: current } })).data.data; selected.value = v.conversation; messages.value = v.items; messagePage.value = v.page; messagePages.value = v.pages; Object.assign(edit, { category: v.conversation.category, status: v.conversation.status, tags: [...v.conversation.tags] }) } catch(e) { failed(e) } }
async function save() { try { await api.patch('/admin/site-assistant/conversations/' + selected.value.id, edit, headers()); await load(); $q.notify({ type: 'positive', message: 'Classificação salva.' }) } catch(e) { failed(e) } }
onMounted(load)
</script>
<template><section class="assistant-admin"><header><div><span>ASSISTENTE DO SITE</span><h2>Da primeira pergunta ao próximo passo.</h2><p>Histórico identificado, origem da conversa e classificação para acompanhar cada oportunidade.</p></div><q-btn flat icon="mdi-refresh" label="Atualizar" :loading="busy" @click="load"/></header><div class="assistant-filters"><q-select v-model="filters.category" :options="['', ...categories]" outlined dark label="Categoria" @update:model-value="page = 1; load()"/><q-select v-model="filters.flow" :options="[{label:'Todos os fluxos',value:''},{label:'Site institucional',value:'site'},{label:'WhatsApp Soluções',value:'whatsapp-solucoes'}]" emit-value map-options outlined dark label="Fluxo de entrada" @update:model-value="page = 1; load()"/></div><div class="assistant-layout" :class="{ selected }"><aside><q-list separator dark><q-item v-for="item in items" :key="item.id" clickable :active="selected?.id === item.id" @click="open(item)"><q-item-section><q-item-label>{{ item.visitor.name }}</q-item-label><q-item-label caption>{{ item.visitor.email || item.visitor.phone }}</q-item-label><div class="q-mt-xs"><q-badge outline>{{ item.category }}</q-badge> <q-badge color="teal-9">{{ item.flow }}</q-badge></div></q-item-section></q-item></q-list><p v-if="!busy && !items.length" class="q-pa-md">Nenhuma conversa neste filtro.</p><q-pagination v-if="pages > 1" v-model="page" :max="pages" color="teal-4" @update:model-value="load"/></aside><main v-if="selected"><header><q-btn flat round icon="mdi-arrow-left" aria-label="Voltar à lista" @click="selected = null"/><div><strong>{{ selected.visitor.name }}</strong><p>{{ selected.visitor.email }} {{ selected.visitor.phone }}</p><small>Origem: {{ selected.pagePath }} · {{ selected.flow }}</small></div></header><div class="conversation-tags"><q-select v-model="edit.category" :options="categories" outlined dark label="Categoria"/><q-select v-model="edit.status" :options="[{label:'Em aberto',value:'open'},{label:'Concluída',value:'closed'}]" emit-value map-options outlined dark label="Situação"/><q-select v-model="edit.tags" multiple use-chips use-input new-value-mode="add-unique" outlined dark label="Etiquetas"/><q-btn color="teal-7" no-caps label="Salvar classificação" @click="save"/></div><div class="assistant-transcript"><q-chat-message v-for="message in messages" :key="message.id" :name="message.role === 'assistant' ? 'AITO' : selected.visitor.name" :text="[message.text]" :sent="message.role === 'assistant'" :stamp="new Date(message.createdAt).toLocaleString('pt-BR')" :bg-color="message.role === 'assistant' ? 'teal-1' : 'grey-2'" text-color="dark"/><p v-if="!messages.length">O visitante se identificou e ainda não enviou mensagens.</p></div><q-pagination v-if="messagePages > 1" v-model="messagePage" :max="messagePages" color="teal-4" @update:model-value="open(selected, $event)"/></main><main v-else class="assistant-empty"><q-icon name="mdi-message-text-outline" size="64px"/><p>Selecione uma conversa para ver o histórico.</p></main></div></section></template>
<style scoped>.assistant-admin{color:#effffb}.assistant-admin>header,.assistant-layout main>header{display:flex;align-items:center;justify-content:space-between;gap:12px}.assistant-admin h2{font-size:26px;margin:6px 0}.assistant-admin p{color:#b9d6d0;font-size:13px}.assistant-admin header span{font-size:10px;letter-spacing:.13em;color:#8fffee}.assistant-filters{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:20px 0}.assistant-layout{display:grid;grid-template-columns:300px 1fr;border:1px solid #2b5855;border-radius:16px;overflow:hidden;min-height:500px}.assistant-layout aside{border-right:1px solid #2b5855;max-height:760px;overflow:auto}.assistant-layout main{padding:20px;min-width:0}.assistant-layout :deep(.q-item--active){background:#17443d}.conversation-tags{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:20px 0}.assistant-transcript{max-height:540px;overflow:auto;padding:12px}.assistant-empty{display:grid;place-content:center;text-align:center}@media(max-width:800px){.assistant-layout{display:block}.assistant-layout.selected aside{display:none}.assistant-layout:not(.selected) main{display:none}.assistant-filters,.conversation-tags{grid-template-columns:1fr}.assistant-layout main{padding:12px}}</style>
